// Агрегация статусов: задача → её позиция → её заказ.
// Все обращения к NocoDB — через this.helpers.httpRequest (доступно в Code-ноде).
const NC = $env.NOCODB_INTERNAL_URL;
const BASE = $env.NC_BASE_ID;
const TOKEN = $env.NC_TOKEN;
const H = { 'xc-token': TOKEN };
const api = (t) => `${NC}/api/v1/db/data/noco/${BASE}/${encodeURIComponent(t)}`;

async function list(t) {
  const r = await this.helpers.httpRequest({ method: 'GET', url: api(t) + '?limit=1000', headers: H, json: true });
  return r.list || [];
}
async function patch(t, id, body) {
  return this.helpers.httpRequest({ method: 'PATCH', url: api(t) + '/' + id, headers: H, body, json: true });
}
// id связанной BT-записи в строке (NocoDB вкладывает belongsTo как объект)
function linkId(v) { if (!v) return null; if (Array.isArray(v)) return v[0]?.Id ?? v[0]?.id ?? null; return v.Id ?? v.id ?? null; }

// статус позиции из статусов её задач
function posStatus(states) {
  if (states.length && states.every((s) => s === 'Выполнено')) return 'Выполнено';
  if (states.includes('В работе')) return 'В работе';
  if (states.includes('Приостановлено')) return 'Приостановлено';
  return 'В очереди';
}
// статус заказа из статусов его позиций
function ordStatus(states) {
  if (states.length && states.every((s) => s === 'Выполнено')) return 'Выполнен';
  if (states.includes('В работе')) return 'В работе';
  if (states.includes('Приостановлено')) return 'Приостановлен';
  return 'Размещён';
}

const body = $input.first().json.body || $input.first().json;
const rows = body?.data?.rows || (body?.data ? [body.data] : []);
const rec = rows[0] || {};
const posId = linkId(rec['Позиции']);
const ordId = linkId(rec['Заказы']);

const allTasks = await list.call(this, 'Задачи на участки');
const allPos = await list.call(this, 'Позиции');

const out = {};

// 1) позиция
if (posId) {
  const states = allTasks.filter((t) => linkId(t['Позиции']) === posId).map((t) => t['Статус']).filter(Boolean);
  const st = posStatus(states);
  await patch.call(this, 'Позиции', posId, { 'Статус': st });
  out.position = { id: posId, status: st };
}

// 2) заказ — собрать его позиции (со свежим статусом позиции)
let orderId = ordId;
if (!orderId && posId) { const p = allPos.find((x) => (x.Id ?? x.id) === posId); orderId = linkId(p?.['Заказы']); }
if (orderId) {
  const states = allPos.filter((p) => linkId(p['Заказы']) === orderId)
    .map((p) => ((p.Id ?? p.id) === posId && out.position) ? out.position.status : p['Статус']).filter(Boolean);
  // ручные статусы заказа не перетираем
  const ord = (await list.call(this, 'Заказы')).find((o) => (o.Id ?? o.id) === orderId);
  const manual = ['Отгружен', 'Закрыт', 'Отменён'];
  if (!manual.includes(ord?.['Статус'])) {
    const st = ordStatus(states);
    await patch.call(this, 'Заказы', orderId, { 'Статус': st });
    out.order = { id: orderId, status: st };
  }
}

return [{ json: out }];
